content.text:
This is the Hash Code 2015 "Optimize a Data Center" problem. The program uses a greedy placement followed by pool assignment, with a local-search improvement step.

**Placement.** Sort servers by capacity/size ratio, descending. Place each server in the row with the least capacity so far, in the first free segment that fits. Segments are the maximal runs of free slots, and the server goes in the first segment of that row that fits. If it fits nowhere in that row, try the other rows in order of increasing capacity. This is cheap and spreads capacity evenly across rows.

**Pool assignment.** Process placed servers in descending capacity order. For each, choose the pool with the lowest guaranteed capacity, breaking ties by the lowest total capacity. Concretely, assign the server to the pool and row that maximizes the resulting minimum guaranteed capacity. A simple version of that rule:

- Keep the per-pool, per-row capacity `cap[p][r]` and the pool total `tot[p]`.
- Guaranteed capacity is `gc[p] = tot[p] - max_r cap[p][r]`.
- For each server, pick the pool with the smallest `gc`, breaking ties by the smaller `tot`.
- Evaluating each pool costs O(R) if the max is recomputed. With P and R up to 1000 and M up to 10^6, scanning all pools per server is too slow.

To avoid that, use a priority queue keyed on `(gc, tot)` per pool. Pop the pool with the lowest `gc`, assign the server to it, recompute its `gc` in O(R), and push it back. The cost is M·(R + log P), which is up to 10^9 in the worst case. To cut it, track the max row capacity for each pool incrementally: adding a server only raises `cap[p][r]`, so the max is updated as `max(mx[p], cap[p][r])`. Each assignment is then O(log P).

The pool with the lowest `gc` gets the next-largest server. Greedy by `gc` alone ignores the row, so the server also lands in whichever row it was placed in. That is acceptable for a baseline.

The memory for `cap[p][r]` is 10^6 ints, which is fine.

```cpp
#include <bits/stdc++.h>
using namespace std;
int main(){
    int R,S,U,P,M;
    scanf("%d %d %d %d %d",&R,&S,&U,&P,&M);
    vector<vector<char>> bad(R, vector<char>(S,0));
    for(int i=0;i<U;i++){int r,s;scanf("%d %d",&r,&s);bad[r][s]=1;}
    vector<int> z(M),c(M);
    for(int i=0;i<M;i++)scanf("%d %d",&z[i],&c[i]);
    vector<int> ord(M);
    iota(ord.begin(),ord.end(),0);
    stable_sort(ord.begin(),ord.end(),[&](int a,int b){
        return (long long)c[a]*z[b]>(long long)c[b]*z[a];
    });
    // segments per row
    vector<vector<pair<int,int>>> seg(R); // start, length remaining
    for(int r=0;r<R;r++){
        int s=0;
        while(s<S){
            if(bad[r][s]){s++;continue;}
            int e=s;
            while(e<S&&!bad[r][e])e++;
            seg[r].push_back({s,e-s});
            s=e;
        }
    }
    vector<long long> rowcap(R,0);
    vector<int> ar(M,-1),as(M,-1),ap(M,-1);
    vector<int> placed;
    for(int idx:ord){
        vector<int> rs(R);
        iota(rs.begin(),rs.end(),0);
        sort(rs.begin(),rs.end(),[&](int a,int b){
            if(rowcap[a]!=rowcap[b])return rowcap[a]<rowcap[b];
            return a<b;
        });
        for(int r:rs){
            bool done=false;
            for(auto&sg:seg[r]){
                if(sg.second>=z[idx]){
                    ar[idx]=r;as[idx]=sg.first;
                    sg.first+=z[idx];sg.second-=z[idx];
                    rowcap[r]+=c[idx];
                    done=true;break;
                }
            }
            if(done)break;
        }
        if(ar[idx]>=0)placed.push_back(idx);
    }
    // pool assignment
    vector<vector<int>> cap(P, vector<int>(R,0));
    vector<long long> tot(P,0),mx(P,0);
    typedef tuple<long long,long long,int> T;
    priority_queue<T,vector<T>,greater<T>> pq;
    for(int p=0;p<P;p++)pq.push(T(0,0,p));
    sort(placed.begin(),placed.end(),[&](int a,int b){
        if(c[a]!=c[b])return c[a]>c[b];
        return a<b;
    });
    for(int idx:placed){
        auto [g,t,p]=pq.top();pq.pop();
        ap[idx]=p;
        int r=ar[idx];
        cap[p][r]+=c[idx];
        tot[p]+=c[idx];
        mx[p]=max(mx[p],(long long)cap[p][r]);
        pq.push(T(tot[p]-mx[p],tot[p],p));
    }
    for(int i=0;i<M;i++){
        if(ar[i]<0)puts("x");
        else printf("%d %d %d\n",ar[i],as[i],ap[i]);
    }
}
```
